window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e7705451712c9b3e"]={"versions": [{"id": "FIG-e7705451712c9b3e", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm / Architekturdiagramm aus dem AUTOSAR-Adaptive-Plattform-Entwurf (<code>AUTOSAR_EXP_PlatformDesign</code>), eingebettet in das Kapitel zum Diagnosekonzept. Das Diagramm illustriert das Modellierungsmuster für eine gemeinsame Diagnoseadresse („Shared diagnostic address 0x1234“) über mehrere Software-Cluster hinweg innerhalb einer Maschine.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst fünf Instanzen des Metatyps <code>Software Cluster</code> und eine Instanz des Metatyps <code>DiagnosticContributionSet</code>:</p>\n<ul class=\"fig-list\">\n<li><code>Platform Core: Software Cluster</code>: Attribute <code>category = PLATFORM_CORE</code> und <code>diagnosticAddress = 0x1234</code>.</li>\n<li><code>Platform: Software Cluster</code>: Attribut <code>category = PLATFORM</code>.</li>\n<li><code>app1: Software Cluster</code>: Attribut <code>category = APPLICATION_LAYER</code>.</li>\n<li><code>app2Root: Software Cluster</code>: Attribut <code>category = APPLICATION_LAYER</code>; besitzt hierarchische Abhängigkeitsbeziehungen (gestrichelte Pfeile) zu Sub-Clustern.</li>\n<li><code>app2Sub1: Software Cluster</code>: Attribut <code>category = APPLICATION_LAYER</code>.</li>\n<li><code>app2Sub2: Software Cluster</code>: Attribut <code>category = APPLICATION_LAYER</code>.</li>\n<li><code>shared: DiagnosticContributionSet</code>: Grau hinterlegte zentrale Entität mit den Attributen <code>DID 0x2314</code> und <code>DID 0x4321</code>.</li>\n</ul>\n<p class=\"fig-p\">Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>Platform Core</code>, <code>Platform</code>, <code>app1</code> und <code>app2Root</code> referenzieren jeweils über gerichtete Pfeilverbindungen die zentrale Entität <code>shared: DiagnosticContributionSet</code>.</li>\n<li><code>app2Root</code> referenziert über gestrichelte Pfeile die beiden untergeordneten Software-Cluster <code>app2Sub1</code> und <code>app2Sub2</code>.</li>\n<li>Assoziierte Textboxen erläutern die Adress- und DID-Teilung sowie den hierarchischen Bezug zur Root-Software-Cluster-Adresse.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurations- und Beziehungsmodell zur Entwurfs- bzw. Manifest-Erstellungszeit:</p>\n<ol class=\"fig-list\">\n<li>Das Root-Software-Cluster <code>Platform Core</code> deklariert die eindeutige Diagnoseadresse <code>0x1234</code> der Maschine.</li>\n<li>Mehrere Software-Cluster (<code>Platform Core</code>, <code>Platform</code>, <code>app1</code>, <code>app2Root</code>) binden sich an dasselbe <code>DiagnosticContributionSet</code> an.</li>\n<li>Durch die gemeinsame Referenzierung erweitern die einzelnen Software-Cluster den Diagnose-Server automatisch um ihre jeweiligen Data Identifier (DID <code>0x2314</code>, DID <code>0x4321</code>), wobei jede DID pro Diagnoseadresse systemweit nur einmalig vergeben werden darf.</li>\n<li>Untergeordnete Cluster (<code>app2Sub1</code>, <code>app2Sub2</code>) werden über das übergeordnete Cluster <code>app2Root</code> strukturell eingebunden.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>In der gezeigten Modellierung deklariert ausschließlich ein einzelnes Root-Software-Cluster (<code>Platform Core</code>) die Diagnoseadresse (<code>diagnosticAddress = 0x1234</code>).</li>\n<li>Alle beteiligten Software-Cluster müssen auf dieselbe Instanz von <code>DiagnosticContributionSet</code> verweisen, um DIDs unter dieser Diagnoseadresse bereitzustellen.</li>\n<li>Eindeutigkeitsregel: Jede DID darf über alle <code>DiagnosticContributionSets</code> einer Diagnoseadresse hinweg nur genau einmal existieren.</li>\n<li>Der Hinweisblock am unteren Rand weist explizit darauf hin, dass die Diagnosekonfiguration aus Gründen der Übersichtlichkeit vereinfacht und unvollständig dargestellt ist.</li>\n</ul>"}, {"id": "FIG-36eb776a2765ccf4", "releases": ["R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm / Architekturdiagramm aus dem AUTOSAR-Adaptive-Plattform-Entwurf (<code>AUTOSAR_EXP_PlatformDesign</code>), eingebettet in das Kapitel zum Diagnosekonzept. Das Diagramm illustriert das Modellierungsmuster für eine gemeinsame Diagnoseadresse („Shared diagnostic address 0x1234“) über mehrere Software-Cluster hinweg innerhalb einer Maschine.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst vier Instanzen des Metatyps <code>Software Cluster</code> und eine Instanz des Metatyps <code>DiagnosticContributionSet</code>:</p>\n<ul class=\"fig-list\">\n<li><code>Platform Core: Software Cluster</code>: Attribut <code>category = PLATFORM_CORE</code>.</li>\n<li><code>Platform: Software Cluster</code>: Attribut <code>category = PLATFORM</code>.</li>\n<li><code>app1: Software Cluster</code>: Attribut <code>category = APPLICATION_LAYER</code>.</li>\n<li><code>app2: Software Cluster</code>: Attribut <code>category = APPLICATION_LAYER</code>.</li>\n<li><code>shared: DiagnosticContributionSet</code>: Grau hinterlegte zentrale Entität mit den Attributen <code>diagnosticAddress = 0x1234</code>, <code>DID 0x2314</code> und <code>DID 0x4321</code>.</li>\n</ul>\n<p class=\"fig-p\">Beziehungen:</p>\n<ul class=\"fig-list\">\n<li>Alle vier Software-Cluster (<code>app1</code>, <code>app2</code>, <code>Platform Core</code>, <code>Platform</code>) besitzen direkte gerichtete Pfeile auf die zentrale Entität <code>shared: DiagnosticContributionSet</code>.</li>\n<li>Assoziierte Textboxen beschreiben die Vergabe der Diagnoseadresse direkt am <code>DiagnosticContributionSet</code> sowie die automatische Erweiterung des Diagnose-Servers durch referenzierende Software-Cluster.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurations- und Beziehungsmodell zur Entwurfs- bzw. Manifest-Erstellungszeit:</p>\n<ol class=\"fig-list\">\n<li>Die Diagnoseadresse <code>0x1234</code> wird zentral im <code>DiagnosticContributionSet</code> (<code>shared</code>) definiert.</li>\n<li>Sämtliche Software-Cluster (<code>Platform Core</code>, <code>Platform</code>, <code>app1</code>, <code>app2</code>) verweisen direkt auf dieses gemeinsame <code>DiagnosticContributionSet</code>.</li>\n<li>Der Diagnose-Server wird durch die Beiträge der angebundenen Software-Cluster automatisch um die definierten DIDs (<code>0x2314</code>, <code>0x4321</code>) erweitert.</li>\n<li>Jede DID darf pro gemeinsamer Diagnoseadresse über alle <code>DiagnosticContributionSets</code> hinweg nur genau einmal existieren.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Zuweisung der Diagnoseadresse erfolgt unmittelbar an der Entität <code>DiagnosticContributionSet</code> (<code>diagnosticAddress = 0x1234</code>) und nicht mehr an einem Software-Cluster.</li>\n<li>Alle Software-Cluster, die dieselbe Diagnoseadresse teilen, referenzieren direkt dasselbe <code>DiagnosticContributionSet</code>.</li>\n<li>Eindeutigkeitsregel: Jede DID darf systemweit für dieselbe Diagnoseadresse nur einmalig vorkommen.</li>\n<li>Der Hinweisblock am unteren Rand stellt klar, dass wesentliche Teile der Diagnosekonfiguration zugunsten der Übersichtlichkeit vereinfacht bzw. ausgelassen wurden.</li>\n</ul>"}], "trans": [{"from": "FIG-e7705451712c9b3e", "to": "FIG-36eb776a2765ccf4", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Verlagerung des Attributs <code>diagnosticAddress = 0x1234</code> von <code>Platform Core: Software Cluster</code> in die Entität <code>shared: DiagnosticContributionSet</code>.</li>\n<li>Konsolidierung der hierarchischen Software-Cluster-Struktur (<code>app2Root: Software Cluster</code> mit gestrichelten Abhängigkeitspfeilen zu <code>app2Sub1: Software Cluster</code> und <code>app2Sub2: Software Cluster</code>) zu einer einzelnen flachen Entität <code>app2: Software Cluster</code> mit direkter Referenz auf <code>shared: DiagnosticContributionSet</code>.</li>\n<li>Anpassung der erklärenden Randnotiz von „Only a single root Software Cluster specifies an diagnostic address.“ zu „Only the DiagnosticContributionSet specifies an diagnostic address.“</li>\n</ul>"}]};
